"""The terminal only receives controls generated by the trusted renderer."""

import unicodedata

from wcwidth import iter_graphemes, wcswidth


def plain(text: object) -> str:
    return "".join(
        f"\\u{ord(char):04x}"
        if (unicodedata.category(char) == "Cc" and char not in "\n\t")
        or unicodedata.bidirectional(char) in {"RLE", "LRE", "RLO", "LRO", "PDF", "RLI", "LRI", "FSI", "PDI"}
        else char
        for char in str(text)
    )


def fit(text: object, width: int) -> str:
    value = plain(text).replace("\n", " ").expandtabs(4)
    if wcswidth(value) <= width:
        return value
    parts = []
    cells = 0
    for grapheme in iter_graphemes(value):
        size = max(0, wcswidth(grapheme))
        if cells + size > max(0, width - 1):
            break
        parts.append(grapheme)
        cells += size
    return "".join(parts) + ("…" if width else "")
